svg.script:
(function(root){
  const valid=['idle','hover','click','talk','success','notify','loading','error','sleep','blink','happy','surprised'];
  const transient={click:720,success:1500,notify:1300};
  let baseState='idle', timer=0;
  function read(){return root.dataset.state||'idle'}
  function dispatch(next,previous){try{root.dispatchEvent(new CustomEvent('petstatechange',{bubbles:true,detail:{state:next,previous:previous,pet:'ProjectHub'}}))}catch(_){}}
  function setState(next,options){
    options=options||{}; if(valid.indexOf(next)<0)return api;
    const previous=read(); if(timer){clearTimeout(timer);timer=0}
    if(!transient[next]&&next!=='hover')baseState=next;
    root.dataset.state=next; dispatch(next,previous);
    const hold=options.duration||transient[next];
    if(hold){const back=options.returnTo||(options.duration?baseState:'idle'); if(back===next)baseState='idle'; timer=setTimeout(function(){setState(back)},hold)}
    return api;
  }
  function pulse(next,duration){return setState(next,{duration:duration||transient[next]||900,returnTo:baseState})}
  const api={states:valid.slice(),setState:setState,pulse:pulse,getState:read,get state(){return read()},set:setState};
  root.ProjectHubPet=api; try{globalThis.ProjectHubPet=api}catch(_){}
  root.addEventListener('pointerenter',function(){if(read()==='idle')setState('hover')});
  root.addEventListener('pointerleave',function(){if(read()==='hover')setState(baseState||'idle')});
  root.addEventListener('click',function(){pulse('click')});
  root.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();pulse('click')}});
  try{globalThis.addEventListener('projecthub:pet-state',function(e){setState(e.detail&&e.detail.state?e.detail.state:e.detail)})}catch(_){}
  try{const q=new URLSearchParams(globalThis.location.search).get('state');if(q&&valid.indexOf(q)>=0)setState(q)}catch(_){}
  if(!root.dataset.state)root.dataset.state='idle';
})((document.currentScript&&document.currentScript.ownerSVGElement)||document.getElementById("pet-root")||document.documentElement);
